'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Lock } from 'lucide-react';

export default function MarksLockPage() {
    const [subjects, setSubjects] = useState<any[]>([]);
    const [locked, setLocked] = useState<Record<string, boolean>>({});

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any[]>('/api/admin/subjects');
                if (res.success) setSubjects(res.data);
            } catch (e) { }
        };
        load();
    }, []);

    const handleLock = async (subjectId: string) => {
        try {
            await api.post(`/api/admin/marks/lock/${subjectId}`);
            setLocked({ ...locked, [subjectId]: true });
        } catch (e) { }
    };

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                Lock Marks
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>
                Lock approved marks to make them visible to students. <strong>This action is irreversible.</strong>
            </p>

            <div className="table-container">
                <table>
                    <thead><tr><th>Subject</th><th>Code</th><th>Max Marks</th><th>Action</th></tr></thead>
                    <tbody>
                        {subjects.length === 0 ? (
                            <tr><td colSpan={4} style={{ textAlign: 'center', padding: 32, color: '#8a9aa2' }}>No subjects found</td></tr>
                        ) : subjects.map(s => (
                            <tr key={s.id}>
                                <td style={{ fontWeight: 600 }}>{s.name}</td>
                                <td><code style={{ fontSize: 13, background: '#f3f4f6', padding: '2px 8px', borderRadius: 4 }}>{s.code}</code></td>
                                <td>{s.max_marks}</td>
                                <td>
                                    {locked[s.id] ? (
                                        <span className="badge badge-success"><Lock size={12} /> Locked</span>
                                    ) : (
                                        <button className="btn-primary btn-sm" onClick={() => handleLock(s.id)}>
                                            <Lock size={14} /> Lock Marks
                                        </button>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
